func sshInvocationArgs(ep *url.URL, service string, gitProtocol string) ([]string, error) {
	destination, err := sshDestination(ep)
	if err != nil {
		return nil, err
	}
	remoteCommand, err := sshRemoteCommand(ep, service)
	if err != nil {
		return nil, err
	}
	args := []string{"-o", "BatchMode=yes"}
	if gitProtocol != "" {
		// Like git; servers may ignore it.
		args = append(args, "-o", "SendEnv=GIT_PROTOCOL")
	}
	if port := ep.Port(); port != "" {
		if err := rejectOptionLike("SSH port", port); err != nil {
			return nil, err
		}
		args = append(args, "-p", port)
	}
	// The "--" terminates ssh option parsing so the destination can never be
	// consumed as a flag; rejectOptionLike below is the portable primary guard
	// (older clients ignore unknown operands but all support "--").
	args = append(args, "--", destination, remoteCommand)
	return args, nil
}

func sshDestination(ep *url.URL) (string, error) {
	if ep == nil || ep.Hostname() == "" {
		return "", errors.New("missing SSH host")
	}
	host := ep.Hostname()
	if err := rejectOptionLike("SSH host", host); err != nil {
		return "", err
	}
	if ep.User != nil && ep.User.Username() != "" {
		user := ep.User.Username()
		if err := rejectOptionLike("SSH username", user); err != nil {
			return "", err
		}
		return user + "@" + host, nil
	}
	return host, nil
}

// rejectOptionLike refuses a destination component that begins with "-". Such
// a value would be parsed by ssh as an option rather than an operand — e.g. a
// host of "-oProxyCommand=..." turns into arbitrary local command execution
// (the class of git's CVE-2017-1000117) — and is never a legitimate host,
// username, or port.
func rejectOptionLike(what, value string) error {
	if strings.HasPrefix(value, "-") {
		return fmt.Errorf("refusing %s %q: must not begin with '-'", what, value)
	}
	return nil
}

// sshRemoteCommand builds the command string sshd hands to the remote login
// shell. Every interpolated component must therefore be shell-quoted.
//
// The path is quoted in full, including any leading "~". Exempting the tilde
// segment so the remote shell would expand it — as this used to — left
// everything up to the first slash unquoted, and a SCP-style URL puts
// attacker-influenced text there: "git@host:~a;id/repo.git" produced the
// remote command `git-upload-pack ~a;id/'repo.git'`, executing `id` on the
// remote host. Quoting costs nothing, because "~" expansion does not depend on
// the shell here: git-upload-pack resolves the path through enter_repo(),
// which interpolates a leading "~" itself. Canonical git quotes the whole path
// for the same reason.
func sshRemoteCommand(ep *url.URL, service string) (string, error) {
	if ep == nil || ep.Path == "" {
		return "", errors.New("missing SSH repository path")
	}
	return service + " " + shellQuote(ep.Path), nil
}

// sshEnv sets GIT_PROTOCOL only when requested.
func sshEnv(base []string, gitProtocol string) []string {
	env := make([]string, 0, len(base)+1)
	for _, kv := range base {
		if !strings.HasPrefix(kv, "GIT_PROTOCOL=") {
			env = append(env, kv)
		}
	}
	if gitProtocol != "" {
		env = append(env, "GIT_PROTOCOL="+gitProtocol)
	}
	return env
}

func shellQuote(s string) string {
	return "'" + strings.ReplaceAll(s, "'", `'"'"'`) + "'"
}

type sshCommand struct {
	Cmd    *exec.Cmd
	Stdin  io.WriteCloser
	Stdout io.ReadCloser
